# pycute_golden.py writes pycute.golden, the independent oracle for
# TestPycuteGolden.
#
# Each case is computed by pycute (NVIDIA/cutlass python/pycute), then checked
# by brute force: a composition must compute A(B(i)) for every i, and a
# complement must make (L, R) a bijection onto [0, size(L)*size(R)). A pycute
# result that fails its check is recorded as "error", because cudalayout
# rejects rather than approximates. $CUTLASS is a checkout of
# https://github.com/NVIDIA/cutlass; the golden file's first line records its
# revision. Regenerate with CUTLASS set and go generate in the package
# directory, or from this directory:
#
#	PYTHONPATH=$CUTLASS/python python3 pycute_golden.py > pycute.golden
import random
import subprocess
import sys

import pycute
from pycute import Layout, coalesce, complement, composition, logical_divide, zipped_divide, size, flatten

rng = random.Random(42)


def fmt(x):
    if isinstance(x, Layout):
        return fmt(x.shape) + ":" + fmt(x.stride)
    s = str(x).replace(" ", "")
    while ",)" in s:
        s = s.replace(",)", ")")
    return s


def leaf(extents, strides):
    return rng.choice(extents), rng.choice(strides)


def tree(depth, extents, strides):
    if depth == 0 or rng.random() < 0.4:
        return leaf(extents, strides)
    n = rng.randint(1 if depth < 2 else 2, 3)
    kids = [tree(depth - 1, extents, strides) for _ in range(n)]
    return tuple(k[0] for k in kids), tuple(k[1] for k in kids)


def layout(depth=2, extents=(1, 2, 3, 4, 6, 8), strides=(0, 1, 2, 3, 4, 6, 8, 12, 16, 24, 32)):
    s, d = tree(depth, extents, strides)
    return Layout(s, d)


def compact(depth=2, extents=(2, 3, 4, 6, 8)):
    s, _ = tree(depth, extents, (1,))
    return Layout(s)


def offsets(l):
    return [l(i) for i in range(size(l))]


def composes(a, b, r):
    return size(r) == size(b) and all(r(i) == a(b(i)) for i in range(size(b)))


def bijective(l, r):
    # A zero extent makes the check vacuous: pycute's complement divides a
    # stride by a larger one and produces extent 0 for overlapping inputs.
    if any(n < 1 for n in flatten(r.shape)):
        return False
    f = pycute.filter(l)
    c = pycute.make_layout(f, r)
    return size(c) > 0 and sorted(offsets(c)) == list(range(size(c)))


def attempt(f):
    try:
        return f()
    except (AssertionError, ZeroDivisionError):
        return None


out = []
rev = subprocess.run(["git", "-C", pycute.__path__[0], "log", "-1", "--format=%h %cs"], capture_output=True, text=True).stdout.strip()
out.append("# generated by pycute_golden.py from NVIDIA/cutlass python/pycute " + rev)

for _ in range(200):
    l = layout()
    if size(l) > 256:
        continue
    out.append("index\t%s\t%s" % (fmt(l), ",".join(map(str, offsets(l)))))
    out.append("coalesce\t%s\t%s" % (fmt(l), fmt(coalesce(l))))
    if isinstance(l.shape, tuple):
        out.append("coalescebymode\t%s\t%s" % (fmt(l), fmt(coalesce(l, (1,) * len(l.shape)))))

for i in range(600):
    a = compact() if i % 2 == 0 else layout(extents=(2, 3, 4, 6, 8), strides=(1, 2, 3, 4, 8, 16))
    b = layout(depth=1, extents=(1, 2, 3, 4, 6, 8), strides=(0, 1, 2, 3, 4, 6, 8))
    r = attempt(lambda: composition(a, b))
    want = fmt(r) if r is not None and composes(a, b, r) else "error"
    out.append("compose\t%s\t%s\t%s" % (fmt(a), fmt(b), want))

for _ in range(300):
    l = layout(depth=1, strides=(0, 1, 2, 3, 4, 6, 8, 12, 16))
    cotarget = rng.choice([1, 8, 24, 64, 96, 128, 256])
    r = attempt(lambda: complement(l, cotarget))
    want = fmt(r) if r is not None and bijective(l, r) and size(pycute.filter(l)) * size(r) >= cotarget else "error"
    out.append("complement\t%s\t%d\t%s" % (fmt(l), cotarget, want))

for _ in range(300):
    a = compact() if rng.random() < 0.6 else layout(extents=(2, 4, 8), strides=(1, 2, 4, 8, 16, 32))
    b = layout(depth=1, extents=(2, 3, 4), strides=(1, 2, 3, 4, 8))
    r = attempt(lambda: logical_divide(a, b))
    ok = r is not None
    if ok:
        c = attempt(lambda: complement(b, size(a)))
        ok = c is not None and bijective(b, c) and composes(a, pycute.make_layout(b, c), r)
    out.append("divide\t%s\t%s\t%s" % (fmt(a), fmt(b), fmt(r) if ok else "error"))

for _ in range(200):
    a = compact(depth=1)
    if not isinstance(a.shape, tuple):
        continue
    k = rng.randint(1, len(a.shape))
    tiler = tuple(Layout(rng.choice([2, 3, 4]), rng.choice([1, 2])) for _ in range(k))
    r = attempt(lambda: zipped_divide(a, tiler))
    ok = r is not None
    if ok:
        for i in range(k):
            c = attempt(lambda: complement(tiler[i], size(a[i])))
            if c is None or not bijective(tiler[i], c) or not composes(a[i], pycute.make_layout(tiler[i], c), logical_divide(a[i], tiler[i])):
                ok = False
    out.append("zipped\t%s\t%s\t%s" % (fmt(a), ";".join(fmt(t) for t in tiler), fmt(r) if ok else "error"))

sys.stdout.write("\n".join(out) + "\n")
